cd /home/nicholas-wood/Documents/workspace/projects/accessbuddy/.worktrees/fob-reissue && W="apps/web/src/app/api/v1/t/[slug]/members/[id]" && mkdir -p "$W/cancel-confirmation" "$W/confirm-on-behalf" && cat > "$W/cancel-confirmation/route.ts" <<'EOF'
import { NextRequest, NextResponse } from "next/server";
import { and, eq } from "drizzle-orm";
import { Permission, AuditEntityType, AuditAction } from "@accessbuddy/shared";
import { attestationRequests } from "@accessbuddy/db";
import { getAuthUser } from "@/lib/auth";
import { resolveTenant } from "@/lib/tenant";
import { checkPermission } from "@/lib/permissions";
import { withTenant } from "@/lib/with-tenant";
import { createAuditEntry } from "@/lib/services/audit";

/**
 * POST /api/v1/t/[slug]/members/[id]/cancel-confirmation
 *
 * Withdraws a pending scoped confirmation (the "member already has this fob"
 * stage of Add Credential). The link stops working, the nightly reminder
 * stops, and the fob can be staged again or edited by hand. Only scoped
 * attestations are cancellable here; a renewal attestation is force-renewed
 * or left to lapse as before. Requires the RENEW permission, like Re-send.
 *
 * Body: { attestationId: string, reason?: string }
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string; id: string }> }
) {
  const auth = await getAuthUser();
  if (!auth) {
    return NextResponse.json({ error: "Authentication required" }, { status: 401 });
  }

  const { slug, id: userId } = await params;
  const tenant = await resolveTenant(slug);
  if (!tenant) {
    return NextResponse.json({ error: "Organisation not found" }, { status: 404 });
  }

  const permResult = checkPermission(auth, tenant.id, Permission.RENEW);
  if (!permResult.granted) {
    return NextResponse.json({ error: permResult.reason }, { status: 403 });
  }

  const body = (await request.json().catch(() => ({}))) as {
    attestationId?: string;
    reason?: string;
  };
  if (!body.attestationId) {
    return NextResponse.json({ error: "attestationId is required" }, { status: 400 });
  }

  const result = await withTenant(tenant.id, async (tx) => {
    const [attestation] = await tx
      .select()
      .from(attestationRequests)
      .where(
        and(
          eq(attestationRequests.id, body.attestationId!),
          eq(attestationRequests.userId, userId),
          eq(attestationRequests.tenantId, tenant.id)
        )
      )
      .limit(1);
    if (!attestation) return { kind: "not_found" as const };
    if (!attestation.credentialIds?.length) return { kind: "not_scoped" as const };
    if (attestation.status !== "pending") return { kind: "not_pending" as const };

    const now = new Date();
    await tx
      .update(attestationRequests)
      .set({ status: "cancelled", updatedAt: now })
      .where(eq(attestationRequests.id, attestation.id));

    await createAuditEntry(tx, {
      tenantId: tenant.id,
      entityType: AuditEntityType.MEMBER,
      entityId: userId,
      action: AuditAction.UPDATE,
      actorId: auth.user.id,
      metadata: {
        action: "attestation_cancelled",
        attestationId: attestation.id,
        season: attestation.season,
        scoped: true,
        credentialIds: attestation.credentialIds,
        reason: body.reason?.trim() || null,
      },
    });
    for (const credentialId of attestation.credentialIds) {
      await createAuditEntry(tx, {
        tenantId: tenant.id,
        entityType: AuditEntityType.CREDENTIAL,
        entityId: credentialId,
        action: AuditAction.UPDATE,
        actorId: auth.user.id,
        metadata: {
          action: "confirmation_cancelled",
          attestationId: attestation.id,
          reason: body.reason?.trim() || null,
        },
      });
    }
