import { NextRequest, NextResponse } from "next/server";
import { and, eq } from "drizzle-orm";
import {
  Permission,
  AuditEntityType,
  AuditAction,
  CredentialStatus,
} from "@accessbuddy/shared";
import { attestationRequests, credentials, credentialTypes } from "@accessbuddy/db";
import { getAuthUser } from "@/lib/auth";
import { resolveTenant } from "@/lib/tenant";
import { checkPermission } from "@/lib/permissions";
import { withTenant } from "@/lib/with-tenant";
import { createAuditEntry } from "@/lib/services/audit";
import { scopedAttestationExpiry } from "@/lib/scoped-attestation";
import { formatExpiryDate } from "@/lib/format-date";

/**
 * POST /api/v1/t/[slug]/members/[id]/confirm-on-behalf
 *
 * The member confirmed in person or by phone that they hold the re-added
 * fob. Does what their "yes" on the confirmation page would do: stages the
 * season expiry and flags the programmer, completes the scoped attestation
 * with the admin recorded as the one who answered. Refuses if the fob has
 * moved on since the confirmation was sent (no longer expired, owned by the
 * member and unflagged). Requires the RENEW permission.
 *
 * Body: { attestationId: string, note?: string }
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string; id: string }> }
) {
  const auth = await getAuthUser();
  if (!auth) {
    return NextResponse.json({ error: "Authentication required" }, { status: 401 });
  }

  const { slug, id: userId } = await params;
  const tenant = await resolveTenant(slug);
  if (!tenant) {
    return NextResponse.json({ error: "Organisation not found" }, { status: 404 });
  }

  const permResult = checkPermission(auth, tenant.id, Permission.RENEW);
  if (!permResult.granted) {
    return NextResponse.json({ error: permResult.reason }, { status: 403 });
  }

  const body = (await request.json().catch(() => ({}))) as {
    attestationId?: string;
    note?: string;
  };
  if (!body.attestationId) {
    return NextResponse.json({ error: "attestationId is required" }, { status: 400 });
  }

  const result = await withTenant(tenant.id, async (tx) => {
    const [attestation] = await tx
      .select()
      .from(attestationRequests)
      .where(
        and(
          eq(attestationRequests.id, body.attestationId!),
          eq(attestationRequests.userId, userId),
          eq(attestationRequests.tenantId, tenant.id)
        )
      )
      .limit(1);
    if (!attestation) return { kind: "not_found" as const };
    if (!attestation.credentialIds?.length) return { kind: "not_scoped" as const };
    if (attestation.status !== "pending") return { kind: "not_pending" as const };

    const now = new Date();
    const newExpiresAt = scopedAttestationExpiry(attestation.season, tenant.timezone, now);
    const staged: string[] = [];
    const skipped: string[] = [];

    for (const credentialId of attestation.credentialIds) {
      const [cred] = await tx
        .select({
          id: credentials.id,
          ownerId: credentials.ownerId,
          status: credentials.status,
          programmingRequired: credentials.programmingRequired,
          serialNumber: credentials.serialNumber,
          typeName: credentialTypes.name,
        })
        .from(credentials)
        .leftJoin(credentialTypes, eq(credentials.credentialTypeId, credentialTypes.id))
        .where(and(eq(credentials.id, credentialId), eq(credentials.tenantId, tenant.id)))
        .limit(1);
      const eligible =
        !!cred &&
        cred.ownerId === userId &&
        cred.status === CredentialStatus.EXPIRED &&
        !cred.programmingRequired;
      if (!eligible) {
        skipped.push(credentialId);
        continue;
      }

      const label = `${cred.typeName ?? "credential"}${cred.serialNumber ? ` #${cred.serialNumber}` : ""}`;
      await tx
        .update(credentials)
        .set({
          pendingExpiresAt: newExpiresAt,
          programmingRequired: true,
          programmingReason: `Admin confirmed on the member's behalf that they hold this ${label} - update expiry to ${formatExpiryDate(newExpiresAt, tenant.timezone)} in the access system and re-enable`,
          programmingRequestedAt: now,
          updatedAt: now,
        })
        .where(and(eq(credentials.id, cred.id), eq(credentials.tenantId, tenant.id)));

      await createAuditEntry(tx, {
        tenantId: tenant.id,
        entityType: AuditEntityType.CREDENTIAL,
        entityId: cred.id,
        action: AuditAction.UPDATE,
        actorId: auth.user.id,
        metadata: {
          action: "attestation_expiry_update",
          season: attestation.season,
          attestationId: attestation.id,
          scoped: true,
          confirmedBy: "admin",
          note: body.note?.trim() || null,
          newExpiresAt: newExpiresAt.toISOString(),
          programmingRequired: true,
        },
      });
      staged.push(cred.id);
    }

    if (staged.length === 0) {
      return { kind: "stale" as const };
    }

    await tx
      .update(attestationRequests)
      .set({
        status: "completed",
        completedAt: now,
        credentialResponses: staged.map((credentialId) => ({
          credentialId,
          confirmed: true,
          note: `Confirmed by admin on the member's behalf${body.note?.trim() ? `: ${body.note.trim()}` : ""}`,
        })),
        updatedAt: now,
      })
      .where(eq(attestationRequests.id, attestation.id));

    await createAuditEntry(tx, {
      tenantId: tenant.id,
      entityType: AuditEntityType.MEMBER,
      entityId: userId,
      action: AuditAction.UPDATE,
      actorId: auth.user.id,
      metadata: {
        action: "attestation_admin_confirmed",
        attestationId: attestation.id,
        season: attestation.season,
        scoped: true,
        credentialIds: staged,
        note: body.note?.trim() || null,
      },
    });

    return { kind: "ok" as const, staged, skipped, newExpiresAt: newExpiresAt.toISOString() };
  });

  if (result.kind === "not_found") {
    return NextResponse.json({ error: "Confirmation not found" }, { status: 404 });
  }
  if (result.kind === "not_scoped") {
    return NextResponse.json(
      { error: "Only a fob confirmation can be answered on the member's behalf" },
      { status: 400 }
    );
  }
  if (result.kind === "not_pending") {
    return NextResponse.json({ error: "Confirmation is no longer pending" }, { status: 409 });
  }
  if (result.kind === "stale") {
    return NextResponse.json(
      {
        error:
          "This fob has changed since the confirmation was sent (no longer expired on this member, or already staged). Cancel the confirmation and check the credential.",
      },
      { status: 409 }
    );
  }
  return NextResponse.json({ confirmed: true, ...result });
}
