import { membershipYearExpiry, midnightInTimezone } from "@/lib/timezone";

/**
 * Expiry a scoped (single-fob) confirmation stages when answered "yes".
 *
 * The attestation carries the season it was raised in ("2026/2027"), whose
 * end is 1 September of the second year. If the member answers after that
 * rollover the season-end date is already in the past and confirm-programming
 * would never reactivate the fob, so fall forward to the current membership
 * year instead. Computed at answer time, never at staging time.
 */
export function scopedAttestationExpiry(
  season: string,
  timezone: string,
  now: Date = new Date()
): Date {
  const match = season.match(/^\d{4}\/(\d{4})$/);
  const seasonEnd = match ? midnightInTimezone(parseInt(match[1], 10), 8, 1, timezone) : null;
  if (seasonEnd && seasonEnd > now) return seasonEnd;
  return membershipYearExpiry(timezone, now);
}

/**
 * Reminder cap for a scoped confirmation: the original email plus this many
 * automatic reminders, after which the cron stops and the admin decides
 * (cancel, confirm on the member's behalf, or re-send by hand).
 */
export const MAX_SCOPED_CONFIRMATION_REMINDERS = 4;
